changeSet.sql:
DO $$ BEGIN
 IF (SELECT count(*) FROM "${schema}".permission WHERE resource='notification' AND action='read')<>1 THEN
  RAISE EXCEPTION 'EMAIL_NOTIFICATION_ENTITLEMENT_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM "${schema}".permission p WHERE p.resource='email_settings'
  AND p.module_id<>(SELECT module_id FROM "${schema}".permission WHERE resource='notification' AND action='read')) THEN
  RAISE EXCEPTION 'EMAIL_PERMISSION_MODULE_CONFLICT'; END IF;
END $$;
INSERT INTO "${schema}".permission(id,resource,action,module_id,description)
SELECT gen_random_uuid(),'email_settings',a.action,m.module_id,a.description
FROM "${schema}".permission m CROSS JOIN (VALUES
 ('read','View safe company email settings (ALL scope)'),
 ('manage','Manage encrypted company email settings (read and ALL scope required)'),
 ('test','Send fixed test to saved sending account (read and ALL scope required)')
) a(action,description) WHERE m.resource='notification' AND m.action='read'
AND NOT EXISTS(SELECT 1 FROM "${schema}".permission p WHERE p.resource='email_settings' AND p.action=a.action);
